/** A stored key, plus the plaintext value the create response returns once and only once. */
type TApiKeyRow = TApiKeyWithEnvironmentPermission & { actualKey?: string };

const ApiKeyDisplay = ({ apiKey }: Readonly<{ apiKey: string }>) => {
  const { t } = useTranslation();
  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(apiKey);
      toast.success(t("workspace.api_keys.api_key_copied_to_clipboard"));
    } catch {
      toast.error(t("workspace.api_keys.unable_to_copy_api_key"));
    }
  };

  if (!apiKey) {
    return <span className="italic">{t("workspace.api_keys.secret")}</span>;
  }

  return (
    <div className="flex items-center justify-between gap-2">
      <span className="break-all whitespace-pre-line">{apiKey}</span>
      {/* `copyApiKeyIcon` is load-bearing: `playwright/lib/utils.ts` waits for and clicks it to read a
          freshly created key, which eight API specs depend on for their bearer token. */}
      <div className="copyApiKeyIcon shrink-0">
        <FilesIcon
          className="size-4 cursor-pointer"
          onClick={(e) => {
            // Stops the click reaching the row, which would open the permissions modal. The column is
            // deliberately not `stopRowClick`: clicking the key *text* has always opened the modal, and
            // only the copy affordance is an exception.
            e.stopPropagation();
            void copyToClipboard();
          }}
          data-testid="copy-button"
        />
      </div>
    </div>
  );
};

/**
 * Exported so `loading.tsx` renders its skeleton from the same column array. That is the whole point of
 * the factory: the old skeleton hand-rolled the header and had drifted to **three** columns against the
 * table's four, which no test could catch.
 *
 * Defined at module level rather than inside the component: an inline `cell` that returns JSX reads as a
 * nested component definition to Sonar (typescript:S6478).
 */
export const getApiKeyColumns = ({
  t,
  locale,
  onDelete,
}: Readonly<{
  t: TFunction;
  locale: TUserLocale;
  onDelete: (event: React.MouseEvent, apiKey: TApiKeyRow) => void;
}>): TSettingsTableColumn<TApiKeyRow>[] => [
  {
    id: "label",
    header: t("common.label"),
    headerClassName: "w-[25%]",
    cellClassName: "font-semibold",
    skeletonWidth: "w-32",
    cell: (apiKey) => apiKey.label,
  },
  {
    id: "apiKey",
    header: t("workspace.api_keys.api_key"),
    headerClassName: "w-[45%]",
    // Replaces `hidden sm:block`, which would have restored a `<td>` to `display: block` and dropped it
    // out of the table's column layout. `hideBelow` uses `table-cell` for exactly that reason.
    hideBelow: "sm",
    skeletonWidth: "w-64",
    cell: (apiKey) => <ApiKeyDisplay apiKey={apiKey.actualKey ?? ""} />,
  },
  {

  {
    id: "createdAt",
    header: t("common.created_at"),
    headerClassName: "w-[20%]",
    skeletonWidth: "w-20",
    cell: (apiKey) => timeSince(apiKey.createdAt.toString(), locale),
  },
  {
    id: "actions",
    header: null,
    srLabel: t("common.actions"),
    headerClassName: "w-[10%]",
    stopRowClick: true,
    skeletonWidth: "w-8",
    // The flex goes on a wrapper inside the cell, never on `cellClassName`: that class lands on the `<td>`
    // itself, and `display: flex` there stops it being a table-cell — which silently kills the shared
    // `align-middle` (`vertical-align` applies only to inline-level and table-cell boxes) and makes the
    // browser wrap the cell in an anonymous table-cell that defaults to baseline alignment. The button
    // would sit high in the row instead of centred. Same reasoning as `hideBelow` above.
    cell: (apiKey) => (
      <div className="flex justify-end">
        <Button
          size="icon"
          variant="ghost"
          aria-label={t("common.delete")}
          onClick={(event) => onDelete(event, apiKey)}>
          <TrashIcon />
        </Button>
      </div>
    ),
  },
];

interface EditAPIKeysProps {
  organizationId: string;
  apiKeys: TApiKeyWithEnvironmentPermission[];
  locale: TUserLocale;
  workspaces: TOrganizationWorkspace[];
  isFormbricksCloud: boolean;
  canGrantOrganizationWriteAccess: boolean;
}

export const EditAPIKeys = ({
  organizationId,
  apiKeys,
  locale,
  workspaces,
  isFormbricksCloud,
  canGrantOrganizationWriteAccess,
}: Readonly<EditAPIKeysProps>) => {
  const { t } = useTranslation();
  const [isAddAPIKeyModalOpen, setIsAddAPIKeyModalOpen] = useState(false);
  const [isDeleteKeyModalOpen, setIsDeleteKeyModalOpen] = useState(false);
  const [apiKeysLocal, setApiKeysLocal] = useState<TApiKeyRow[]>(apiKeys);
  const [activeKey, setActiveKey] = useState<TApiKeyWithEnvironmentPermission | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [viewPermissionsOpen, setViewPermissionsOpen] = useState(false);

  const handleOpenDeleteKeyModal = (e: React.MouseEvent, apiKey: TApiKeyWithEnvironmentPermission) => {
    e.preventDefault();
    setActiveKey(apiKey);
    setIsDeleteKeyModalOpen(true);
  };

  const handleDeleteKey = async () => {
    if (!activeKey) return;
    setIsLoading(true);
    const deleteApiKeyResponse = await deleteApiKeyAction({ id: activeKey.id });
    if (deleteApiKeyResponse?.data) {
      const updatedApiKeys = apiKeysLocal?.filter((apiKey) => apiKey.id !== activeKey.id) || [];
      setApiKeysLocal(updatedApiKeys);
      toast.success(t("workspace.api_keys.api_key_deleted"));
      setIsDeleteKeyModalOpen(false);
      setIsLoading(false);
    } else {
      toast.error(t("workspace.api_keys.unable_to_delete_api_key"));
      setIsDeleteKeyModalOpen(false);
      setIsLoading(false);
    }
  };

  const handleAddAPIKey = async (data: {
    label: string;
    workspacePermissions: Array<{
      permission: ApiKeyPermission;
      workspaceId: string;
    }>;
    organizationAccess: TOrganizationAccess;
  }): Promise<void> => {
    setIsLoading(true);
    const createApiKeyResponse = await createApiKeyAction({
      organizationId: organizationId,
      apiKeyData: {
        label: data.label,
        workspacePermissions: data.workspacePermissions,
        organizationAccess: data.organizationAccess,
      },
    });

    if (createApiKeyResponse?.data) {
      const updatedApiKeys = [...apiKeysLocal, createApiKeyResponse.data];
      setApiKeysLocal(updatedApiKeys);
      setIsLoading(false);
      toast.success(t("workspace.api_keys.api_key_created"));
    } else {
      setIsLoading(false);
      const errorMessage = getFormattedErrorMessage(createApiKeyResponse);
      toast.error(errorMessage);
    }

    setIsAddAPIKeyModalOpen(false);
  };

  const handleUpdateAPIKey = async (data: TApiKeyUpdateInput) => {
    if (!activeKey) return;

    const updateApiKeyResponse = await updateApiKeyAction({
      apiKeyId: activeKey.id,
      apiKeyData: data,
    });

    if (updateApiKeyResponse?.data) {
      const updatedApiKeys =
        apiKeysLocal?.map((apiKey) => {
          if (apiKey.id === activeKey.id) {
            return {
              ...apiKey,
              label: data.label,
            };
          }
          return apiKey;
        }) || [];

      setApiKeysLocal(updatedApiKeys);
      toast.success(t("workspace.api_keys.api_key_updated"));
      setIsLoading(false);
    } else {
      const errorMessage = getFormattedErrorMessage(updateApiKeyResponse);
      toast.error(errorMessage);
      setIsLoading(false);
    }

    setViewPermissionsOpen(false);
  };

  return (
    <>
      {/* Moved above the table, matching every other settings table in this series — and required, since
          a flush card body means the table has to be the last thing in it. The control carries the card's
          gutter itself. */}
      <div className="mb-4 flex justify-end px-4 pt-4">
        <Button
          size="sm"
          onClick={() => {
            setIsAddAPIKeyModalOpen(true);
          }}>
          {t("workspace.settings.api_keys.add_api_key")}
        </Button>
      </div>

      <SettingsTable
        columns={getApiKeyColumns({ t, locale, onDelete: handleOpenDeleteKeyModal })}
        rows={apiKeysLocal}
        getRowId={(apiKey) => apiKey.id}
        emptyMessage={t("workspace.api_keys.no_api_keys_yet")}
        getRowProps={() => ({ "data-testid": "api-key-row" })}
        aria-label={t("common.api_keys")}
        onRowClick={(apiKey) => {
          setActiveKey(apiKey);
          setViewPermissionsOpen(true);
        }}
        getRowLabel={(apiKey) => t("workspace.api_keys.view_permissions_for", { label: apiKey.label })}
      />

      <AddApiKeyModal
        open={isAddAPIKeyModalOpen}
        setOpen={setIsAddAPIKeyModalOpen}
        onSubmit={handleAddAPIKey}
        workspaces={workspaces}
        isCreatingAPIKey={isLoading}
        isFormbricksCloud={isFormbricksCloud}
        canGrantOrganizationWriteAccess={canGrantOrganizationWriteAccess}
      />
      {activeKey && (
        <ViewPermissionModal
          open={viewPermissionsOpen}
          setOpen={setViewPermissionsOpen}
          onSubmit={handleUpdateAPIKey}
          apiKey={activeKey}
          workspaces={workspaces}
          isUpdating={isLoading}
        />
      )}
      <DeleteDialog
        open={isDeleteKeyModalOpen}
        setOpen={setIsDeleteKeyModalOpen}
        deleteWhat={t("workspace.api_keys.api_key")}
        onDelete={handleDeleteKey}
        isDeleting={isLoading}
        text={t("workspace.api_keys.delete_api_key_confirmation")}
      />
    </>
  );
};

import { cn } from "@/lib/cn";
import { Skeleton } from "@/modules/ui/components/skeleton";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/modules/ui/components/table";
import { getBodyCellClassName, getFrameClassName, getHeaderCellClassName } from "./lib/column-classes";
import type { TSettingsTableColumn, TSettingsTableSkeletonProps } from "./types";

const DEFAULT_SKELETON_ROWS = 3;

/**
 * Skeleton body rows for a table that is already rendering its own header. Kept separate from
 * `SettingsTableSkeleton` so `SettingsTable`'s `isLoading` state can swap only the body and leave the
 * real header in place.
 */
export const SettingsTableSkeletonRows = <TRow,>({
  columns,
  rows = DEFAULT_SKELETON_ROWS,
}: Readonly<{ columns: TSettingsTableColumn<TRow>[]; rows?: number }>) => (
  <>
    {Array.from({ length: rows }, (_, rowIndex) => (
      <TableRow key={`settings-table-skeleton-row-${rowIndex}`}>
        {columns.map((column) => (
          <TableCell key={column.id} className={getBodyCellClassName(column)}>
            <Skeleton className={cn("h-4 rounded-xl", column.skeletonWidth ?? "w-24")} />
          </TableCell>
        ))}
      </TableRow>
    ))}
  </>
);

/**
 * A full loading table for `loading.tsx` files. Pass the **same column array** the real table uses —
 * importing it from a shared `getXColumns(t, flags)` factory is what stops the skeleton drifting out of
 * sync with the table it stands in for.
 */
export const SettingsTableSkeleton = <TRow,>({
  columns,
  frame = "none",
  rows = DEFAULT_SKELETON_ROWS,
  className,
  containerClassName,
}: Readonly<TSettingsTableSkeletonProps<TRow>>) => (
  <div className={cn(getFrameClassName(frame), containerClassName)}>
    <Table className={className}>
      <TableHeader>
        <TableRow className="bg-slate-100">
          {columns.map((column) => (
            <TableHead key={column.id} className={getHeaderCellClassName(column)}>
              {column.header}
              {column.header === null && column.srLabel ? (
                <span className="sr-only">{column.srLabel}</span>
              ) : null}
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        <SettingsTableSkeletonRows columns={columns} rows={rows} />
      </TableBody>
    </Table>
  </div>
);

import type { ReactNode } from "react";

export type TSettingsTableAlign = "left" | "center" | "right";
export type TSettingsTableBreakpoint = "sm" | "md" | "lg";

/**
 * `none` — the table draws no frame, because a `<SettingsCard bodyVariant="flush">` already frames it.
 * `card` — the table draws its own frame, for use outside a settings card.
 */
export type TSettingsTableFrame = "none" | "card";

export type TSettingsTableColumn<TRow> = {
  /** Stable identifier, used as the React key for this column's header and every one of its cells. */
  id: string;
  /** Already-translated header label. `null` renders an empty header cell — pair it with `srLabel`. */
  header: ReactNode;
  cell: (row: TRow, index: number) => ReactNode;
  /**
   * Sets `text-align` on the header cell and every body cell in this column. Defaults to `left`.
   *
   * It moves **inline-level** content, which covers text, badges and `Button`/`Link` (both `inline-flex`).
   * It cannot move a block-level child, so a cell whose content is a wrapper `<div>` — or the skeleton's
   * placeholder bar — is unaffected by it. Declaring it alongside a flex wrapper is therefore inert; pick
   * one and let it be the only alignment source for the column.
   */
  align?: TSettingsTableAlign;
  /** Hides the column below this breakpoint. Applied to the header and body cells together. */
  hideBelow?: TSettingsTableBreakpoint;
  /**
   * Extra classes merged onto the `<th>`.
   *
   * This is where a column's **width** belongs (`w-[22%]`, `w-16`), because the header cell is what
   * sizes the whole column — putting a width on `cellClassName` only affects that one cell. Widths are
   * suggestions rather than commands: the table is `table-auto`, so a long value can still borrow space
   * from a short one, and when a `hideBelow` column drops out the remaining widths rescale.
   */
  headerClassName?: string;
  /**
   * Extra classes merged onto every `<td>` in this column, e.g. `font-medium text-slate-900`.
   *
   * **Do not change the cell's `display` here** — no `flex`, `grid` or `block`. These classes land on the
   * `<td>` itself, so overriding `display` stops it being a table-cell: the shared `align-middle` becomes
   * a no-op (`vertical-align` applies only to inline-level and table-cell boxes) and the browser wraps the
   * cell in an anonymous table-cell that defaults to baseline, so the content sits high in the row. To lay
   * cell content out, put the flex on a wrapper element **inside** `cell` instead. (`hideBelow` exists for
   * the same reason — it uses `table-cell`, not `block`.)
   */
  cellClassName?: string;
  /** Accessible name for a header cell whose `header` is `null` — typically an actions column. */
  srLabel?: string;
  /** Clicks inside this column do not activate the row. Use for action buttons and nested links. */
  stopRowClick?: boolean;
  /** Width of this column's skeleton bar. Defaults to `w-24`. */
  skeletonWidth?: `w-${string}`;
};

type SettingsTableBaseProps<TRow> = {
  columns: TSettingsTableColumn<TRow>[];
  rows: TRow[];
  getRowId: (row: TRow) => string;
  /** Already-translated. Rendered in a full-width cell when there are no rows. */
  emptyMessage: string;
  frame?: TSettingsTableFrame;
  isLoading?: boolean;
  skeletonRows?: number;
  /** Dims the row and blocks its interactions, e.g. while a sibling row's action is in flight. */
  isRowDisabled?: (row: TRow) => boolean;
  /** Non-row content rendered inside the frame, below the table — and outside its horizontal scroll. */
  footer?: ReactNode;
  /** Per-row DOM hooks. Prefer `data-testid` over `id`, which is not unique across rows. */
  getRowProps?: (row: TRow) => { id?: string; "data-testid"?: string };
  bodyProps?: { id?: string };
  id?: string;
  "aria-label"?: string;
  "data-testid"?: string;
  /** Classes for the `<table>` itself. */
  className?: string;
  /** Extra classes for the frame wrapper, e.g. a width constraint. Merged after `frame`. */
  containerClassName?: string;
};

/**
 * `getRowLabel` is required alongside `onRowClick`: the row's activator is a real `<button>`, and a
 * button built out of arbitrary cell content needs an accessible name.
 */
type SettingsTableClickProps<TRow> =
  | { onRowClick?: never; getRowLabel?: never; isRowClickable?: never }
  | {
      onRowClick: (row: TRow) => void;
      getRowLabel: (row: TRow) => string;
      isRowClickable?: (row: TRow) => boolean;
    };

export type TSettingsTableProps<TRow> = SettingsTableBaseProps<TRow> & SettingsTableClickProps<TRow>;

export type TSettingsTableSkeletonProps<TRow> = Pick<
  SettingsTableBaseProps<TRow>,
  "columns" | "frame" | "className" | "containerClassName"
> & { rows?: number };

